/// <summary>
/// The <c>METSalesTableForm_Extension</c> class is an extension class which extends the <c>SalesTable</c> form initialization functionality.
/// </summary>
[ExtensionOf(formStr(SalesTable))]
internal final class METSalesTableForm_Extension
{

}

Method.Source:
/// <summary>
/// Performs additional actions when the sales order is created.
/// </summary>
protected void salesTableCreated()
{
    next salesTableCreated();

    METSalesTable.data(SysExtensionSerializerExtensionMap::findByBase(
        METSalesTable.TableId,
        SalesTable.RecId,
        true));

    METSalesTable_ds.rereadReferenceDataSources();
}
